export const getPhotosByCategory = (categoryId: string): CampusPhoto[] => {
    if (!categoryId || categoryId === 'all') return ALL_CAMPUS_PHOTOS;
    return ALL_CAMPUS_PHOTOS.filter(p => p.categoryId === categoryId || p.folder === categoryId);
};

export const getPhotosByFolder = (folderName: string): CampusPhoto[] => {
    return ALL_CAMPUS_PHOTOS.filter(p => p.folder === folderName);
};

export const getCategoryMeta = (categoryId: string): PhotoCategory | undefined => {
    return PHOTO_CATEGORIES.find(c => c.id === categoryId || c.folder === categoryId);
};
